import test from 'node:test';
import assert from 'node:assert/strict';
import { compileFilter } from '../src/queryDsl.mjs';
import { getBillingWindowBounds, enumerateDailyWindows } from '../src/clock.mjs';

test('queryDsl compiles basic comparisons and AND', () => {
  const pred = compileFilter('status == "ok" AND count >= 10');
  assert.equal(pred({ status: 'ok', count: 12 }), true);
  assert.equal(pred({ status: 'ok', count: 5 }), false);
  assert.equal(pred({ status: 'err', count: 12 }), false);
});

test('clock computes UTC and winter New York windows', () => {
  const utcWin = getBillingWindowBounds(Date.UTC(2026, 0, 15, 14, 30, 0), 'UTC', 0);
  assert.equal(utcWin.localDate, '2026-01-15');
  assert.equal(utcWin.startUtcMs, Date.UTC(2026, 0, 15, 0, 0, 0));
  assert.equal(utcWin.endUtcMs, Date.UTC(2026, 0, 16, 0, 0, 0));

  const nyWin = getBillingWindowBounds(Date.UTC(2026, 0, 15, 15, 0, 0), 'America/New_York', 0);
  assert.equal(nyWin.localDate, '2026-01-15');
  assert.equal(nyWin.startUtcMs, Date.UTC(2026, 0, 15, 5, 0, 0));

  const list = enumerateDailyWindows(Date.UTC(2026, 0, 15, 0, 0, 0), Date.UTC(2026, 0, 17, 0, 0, 0), 'UTC', 0);
  assert.equal(list.length, 2);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { IdempotencyGuard } from '../src/idempotencyGuard.mjs';
import { BatchIngestor } from '../src/batchIngestor.mjs';
import { ERROR_CODES } from '../src/errors.mjs';

test('IdempotencyGuard accepts fresh, flags active duplicate, rejects conflict', () => {
  const guard = new IdempotencyGuard({ ttlMs: 10_000, maxEntries: 100 });
  const r1 = guard.checkAndRecord('evt-1', 'hash-a', 1000);
  assert.equal(r1.status, 'accepted');

  const r2 = guard.checkAndRecord('evt-1', 'hash-a', 2000);
  assert.equal(r2.status, 'duplicate');
  assert.equal(r2.originalRecordedAtMs, 1000);

  assert.throws(
    () => guard.checkAndRecord('evt-1', 'hash-b', 2500),
    (err) => err.code === ERROR_CODES.ERR_IDEMPOTENCY_CONFLICT
  );
});

test('BatchIngestor sequential ingest and flush', async () => {
  const flushed = [];
  const ingestor = new BatchIngestor({
    maxBatchSize: 2,
    sinkFn: async (batch) => {
      flushed.push(batch);
    }
  });
  await ingestor.ingest({ seq: 1, metric: 'tokens', units: 10 });
  assert.equal(ingestor.pendingCount, 1);
  await ingestor.ingest({ seq: 2, metric: 'tokens', units: 20 });
  assert.equal(ingestor.pendingCount, 0);
  assert.equal(ingestor.committedWatermarkSeq, 2);
  assert.equal(ingestor.totalCommitted, 2);
  assert.equal(flushed.length, 1);
});
